#!/usr/bin/env node
import { readFileSync as readCarrierInput } from "node:fs";
import { resolve } from "node:path";
import {
  EMPTY_WITNESS_ROOT,
  identifyJsonSemanticContent,
} from "../semiotic-expression-notation/runtime.mjs";
import { jsonToTerm } from "../semiotic-expression-notation/json-codec.mjs";
import { tm } from "../semiotic-expression-notation/notation.mjs";
import { dataArtifactAddress } from "@red-cup-engineering/eavt-services-section/data-artifact-address";
import { toEavt } from "@red-cup-engineering/eavt-services-section/row";
import { seavtRow } from "./admit-seavt-row.mjs";
import { eventForRow } from "./journal/filesystem/events.mjs";
import { segmentAdmit } from "./journal/filesystem/segment-store.mjs";
import { querySemanticRecords } from "./query-semantic-records.mjs";

/** The FOUR charge a record's evidence pair names: neither side, for only, against only, or both. */
export function chargeOfTold({ for: forSide, against }) {
  return forSide ? (against ? "contested" : "held") : (against ? "denied" : "unknown");
}
/** The claim a semantic record is admitted under: its charge. */
export const semanticRecordClaim = (told) => tm.mark(`semantic-record.${chargeOfTold(told)}`);
/** The claim a relation asserted beside a semantic record is admitted under. */
export const SEMANTIC_RELATION_CLAIM = tm.mark("semantic-record.relation");

/** The journal feed a kind of semantic record is admitted into, for one date. */
export function semanticRecordFeed(root, objectKind, at) {
  return dataArtifactAddress({ root, tier: "log", encoding: "jsonl", at, action: objectKind, subject: objectKind }).path;
}

export const inputSchema = {
  type: "object",
  properties: {
    root: { type: "string", minLength: 1 },
    objectKind: { type: "string", minLength: 1 },
    category: { type: "string", minLength: 1 },
    record: {},
    recordedAt: {},
    told: {
      type: "object",
      properties: {
        for: { type: "boolean" },
        against: { type: "boolean" },
      },
      required: ["for", "against"],
      additionalProperties: false,
    },
    relation: {
      type: "object",
      properties: { subject: {}, predicate: {}, object: {} },
      required: ["subject", "predicate", "object"],
      additionalProperties: false,
    },
    causes: { type: "array", items: { type: "string" } },
    origin: { type: "string", minLength: 1 },
  },
  required: [
    "root",
    "objectKind",
    "category",
    "record",
    "recordedAt",
    "told",
  ],
  additionalProperties: false,
};
export const outputSchema = {
  type: "object",
  properties: {
    id: { type: "string", minLength: 1 },
    objectKind: { type: "string", minLength: 1 },
    appended: { type: "integer", minimum: 0 },
    events: { type: "array", items: { type: "string" } },
    told: {
      type: "object",
      properties: {
        for: { type: "boolean" },
        against: { type: "boolean" },
      },
      required: ["for", "against"],
      additionalProperties: false,
    },
  },
  required: ["id", "objectKind", "appended", "events", "told"],
  additionalProperties: false,
};
export function recordSemanticRecord({
  root,
  objectKind,
  category,
  record: value,
  recordedAt,
  told,
  relation,
  causes = [],
  origin,
} = {}) {
  if (
    typeof root !== "string" ||
    root.length === 0 ||
    typeof objectKind !== "string" ||
    objectKind.length === 0 ||
    typeof category !== "string" ||
    category.length === 0
  )
    throw new TypeError(
      "Semantic record journal root, objectKind, and category are required",
    );
  if (
    !told ||
    Object.getPrototypeOf(told) !== Object.prototype ||
    typeof told.for !== "boolean" ||
    typeof told.against !== "boolean"
  )
    throw new TypeError(
      "Semantic record journal told requires independent for and against booleans",
    );
  const custodyRoot = resolve(root);
  const kind = objectKind;
  const observed = told;
  const identity = identifyJsonSemanticContent({
    objectKind: kind,
    value,
    witnessRoot: EMPTY_WITNESS_ROOT,
  });
  const rows = [
    seavtRow({
      e: jsonToTerm(identity.id),
      a: jsonToTerm(category),
      v: jsonToTerm(value),
      t: recordedAt,
    }),
  ];
  if (relation !== undefined) {
    if (
      !relation ||
      Object.getPrototypeOf(relation) !== Object.prototype ||
      !Object.hasOwn(relation, "subject") ||
      !Object.hasOwn(relation, "predicate") ||
      !Object.hasOwn(relation, "object")
    )
      throw new TypeError(
        "Semantic record journal relation requires subject, predicate, and object",
      );
    rows.push(
      seavtRow({
        e: jsonToTerm(relation.subject),
        a: jsonToTerm(relation.predicate),
        v: jsonToTerm(relation.object),
        t: recordedAt,
      }),
    );
  }
  // The record row carries the record's evidence as its claim; a relation row is asserted beside it
  // under its own claim, so a reader of records never takes a relation for one.
  const statements = rows.map((row, index) => eventForRow(toEavt(row), origin ?? kind, {
    claim: index === 0 ? semanticRecordClaim(observed) : SEMANTIC_RELATION_CLAIM,
    causes,
  }));
  const results = segmentAdmit(semanticRecordFeed(custodyRoot, kind, recordedAt), statements);
  return Object.freeze({
    id: identity.id,
    objectKind: kind,
    appended: results.filter((result) => result.written).length,
    events: Object.freeze(statements.map((statement) => statement.id)),
    told: Object.freeze({ ...observed }),
  });
}
/** A semantic record journal bound to one custody root and default object
 * kind: `record` and `query` take the rest of a request, and a request may
 * name its own `objectKind`. */
export function createSemanticRecordJournal({ root, objectKind: defaultObjectKind } = {}) {
  const custodyRoot = resolve(root);
  return Object.freeze({
    root: custodyRoot,
    record: (request) => recordSemanticRecord({ ...request, root: custodyRoot, objectKind: request?.objectKind ?? defaultObjectKind }),
    query: (request) => querySemanticRecords({ ...request, root: custodyRoot, objectKind: request?.objectKind ?? defaultObjectKind }),
  });
}

/**
 * A settlement store over one journal: an actor's records, each kept under a category and
 * asserted as `actor records <record id or category>`, told for and not against unless the
 * request says otherwise, and read back by category.
 */
export function createSettlementStore({ settlementRoot, objectKind, actor } = {}) {
  const journal = createSemanticRecordJournal({ root: settlementRoot, objectKind });
  return Object.freeze({
    root: journal.root,
    record: ({ category, recordedAt, record, told = { for: true, against: false }, relation }) => journal.record({
      category, recordedAt, record, told,
      relation: relation ?? { subject: actor, predicate: "records", object: record?.id ?? category },
    }),
    records: (category) => journal.query({ category }).map((row) => structuredClone(row.record)),
  });
}

/** The records one settlement journal keeps under a category. */
export function querySettlementRecords(category, { root, objectKind } = {}) {
  return createSemanticRecordJournal({ root, objectKind }).query({ category }).map((row) => structuredClone(row.record));
}

if (import.meta.main)
  process.stdout.write(
    JSON.stringify(
      recordSemanticRecord(JSON.parse(readCarrierInput(0, "utf8"))),
    ) + "\n",
  );

#!/usr/bin/env node
import { readFileSync as readCarrierInput } from "node:fs";
import { existsSync, readdirSync } from "node:fs";
import { join, resolve } from "node:path";
import { canonicalJson } from "@red-cup-engineering/json-services-section";
import { dataArtifactAddress } from "@red-cup-engineering/eavt-services-section/data-artifact-address";
import {
  EMPTY_WITNESS_ROOT,
  identifyJsonSemanticContent,
} from "../semiotic-expression-notation/runtime.mjs";
import { termToJson } from "../semiotic-expression-notation/json-codec.mjs";
import { tm } from "../semiotic-expression-notation/notation.mjs";
import { readSeavtEntriesAtPath } from "./read-seavt-entries-at-path.mjs";
import { journalDirectoryOf } from "./journal/store-root.mjs";
import { segmentPath, segmentStatements } from "./journal/filesystem/segment-store.mjs";

/** The feed every semantic record was appended to before records were journal witnesses. */
const LEGACY_FEED = "witness-journal-seavt";
const TOLD = Object.freeze({
  unknown: Object.freeze({ for: false, against: false }),
  held: Object.freeze({ for: true, against: false }),
  denied: Object.freeze({ for: false, against: true }),
  contested: Object.freeze({ for: true, against: true }),
});
const CHARGE_OF_CLAIM = new Map(Object.keys(TOLD).map((charge) => [canonicalJson(tm.mark(`semantic-record.${charge}`)), charge]));

export const inputSchema = {
  type: "object",
  properties: {
    root: { type: "string", minLength: 1 },
    objectKind: { type: "string", minLength: 1 },
    category: { type: "string", minLength: 1 },
  },
  required: ["root", "objectKind", "category"],
  additionalProperties: false,
};
export const outputSchema = { type: "array", items: { type: "object" } };

/** The dated directories (YYYY/MM/DD) under one tier directory, as dates, in order. */
function datesUnder(directory) {
  const dates = [];
  const list = (path, pattern) => {
    try {
      return readdirSync(path, { withFileTypes: true }).filter((entry) => entry.isDirectory() && pattern.test(entry.name)).map((entry) => entry.name).sort();
    } catch (error) {
      if (error.code === "ENOENT") return [];
      throw error;
    }
  };
  for (const year of list(directory, /^\d{4}$/u)) {
    for (const month of list(join(directory, year), /^\d{2}$/u)) {
      for (const day of list(join(directory, year, month), /^\d{2}$/u)) dates.push(`${year}-${month}-${day}`);
    }
  }
  return dates;
}

/** Records of one kind and category admitted into the journal as witnesses. */
function journalRecords(root, kind, category) {
  const records = [];
  for (const date of datesUnder(journalDirectoryOf(root))) {
    const logPath = dataArtifactAddress({ root, tier: "log", encoding: "jsonl", at: date, action: kind, subject: kind }).path;
    if (!existsSync(segmentPath(logPath))) continue;
    for (const statement of segmentStatements(logPath)) {
      const row = statement.observation.payload;
      if (!Array.isArray(row) || row.length !== 4) continue;
      const [e, a, v, t] = row;
      if (termToJson(a) !== category) continue;
      const charge = CHARGE_OF_CLAIM.get(canonicalJson(statement.observation.claim));
      if (charge === undefined) continue;
      records.push(Object.freeze({
        id: termToJson(e),
        objectKind: kind,
        category,
        recordedAt: t,
        record: termToJson(v),
        told: TOLD[charge],
        event: statement.id,
        origin: statement.observation.seat,
        causes: statement.core.causes,
      }));
    }
  }
  return records;
}

/** Records written to the SEAVT feed before records were journal witnesses: a record is of a kind when its id is its content's address under that kind. */
function legacyRecords(root, kind, category) {
  const records = [];
  const files = (directory) => {
    const found = [];
    try {
      for (const item of readdirSync(directory, { withFileTypes: true })) {
        const path = join(directory, item.name);
        if (item.isDirectory()) found.push(...files(path));
        else if (item.isFile() && item.name === `${LEGACY_FEED}.jsonl`) found.push(path);
      }
    } catch (error) {
      if (error.code !== "ENOENT") throw error;
    }
    return found.sort();
  };
  for (const path of files(join(root, "data", "logs"))) {
    for (const row of readSeavtEntriesAtPath({ path })) {
      if (termToJson(row.a) !== category) continue;
      const id = termToJson(row.e);
      const value = termToJson(row.v);
      if (identifyJsonSemanticContent({ objectKind: kind, value, witnessRoot: EMPTY_WITNESS_ROOT }).id !== id) continue;
      records.push(Object.freeze({ id, objectKind: kind, category, recordedAt: row.t, record: value }));
    }
  }
  return records;
}

/** Every record of one kind and category, from the journal and from the earlier SEAVT feed, once each, in the order recorded. */
export function querySemanticRecords({ root, objectKind, category } = {}) {
  if (
    typeof root !== "string" ||
    !root ||
    typeof objectKind !== "string" ||
    !objectKind ||
    typeof category !== "string" ||
    !category
  )
    throw new TypeError(
      "Semantic record journal root, objectKind, and category are required",
    );
  const custodyRoot = resolve(root);
  const seen = new Set();
  const records = [];
  for (const record of [...legacyRecords(custodyRoot, objectKind, category), ...journalRecords(custodyRoot, objectKind, category)]) {
    const key = canonicalJson([record.id, record.recordedAt]);
    if (seen.has(key)) continue;
    seen.add(key);
    records.push(record);
  }
  return Object.freeze(records.map((record, index) => ({ record, index }))
    .sort((left, right) => String(left.record.recordedAt).localeCompare(String(right.record.recordedAt)) || left.index - right.index)
    .map(({ record }) => record));
}
if (import.meta.main)
  process.stdout.write(
    JSON.stringify(
      querySemanticRecords(JSON.parse(readCarrierInput(0, "utf8"))),
    ) + "\n",
  );

/** Journal-facing construction and verification of witnessed observations. */
import { createHash } from "node:crypto";
import {
  addressArtifact,
  addressSiteConstitution,
  addressPrimitiveArticulation,
  verifyArtifact,
  isArtifactRef,
} from "../identity/index.mjs";
import {
  canonicalJson,
  requireJsonValue,
  canonicalizeJson,
  JSON_RESOURCE_ENVELOPE,
} from "@red-cup-engineering/json-services-section";
import {
  isClosed,
  inferTy,
  checkTy,
} from "@red-cup-engineering/computer-code-engineering-services-section/semiotic-expression-notation/typing";
import { tm } from "@red-cup-engineering/computer-code-engineering-services-section/semiotic-expression-notation";
import { eavtKey } from "@red-cup-engineering/eavt-services-section/row";
import { isCausalWitness } from "./judgment.mjs";
import { addressWitnessCore } from "./witness.mjs";

const UNIQUE_COMMAND = "metroplat.journal.unique-command";
const UNIQUE_ADMISSION = "metroplat.journal.unique-admission";
const UNIQUE_RECORD = "metroplat.journal.unique-record";
const ENVELOPE = Object.freeze({
  maxSourceBytes: 1048576,
  maxCanonicalBytes: 1048576,
  maxDepth: 64,
  maxNodes: 100000,
  maxObjectMembers: 4096,
  maxArrayLength: 65536,
  maxStringBytes: 262144,
  maxKeyBytes: 1024,
});

function check(term, type) {
  return isClosed(term) && (type === undefined ? inferTy([], term) !== null : checkTy([], term, type));
}

function bad(field) {
  const error = new TypeError(`unique journal ${field} is invalid`);
  error.code = "unique-journal-invalid";
  throw error;
}

function guard(run) {
  try {
    return run();
  } catch (error) {
    if (error?.code === "unique-journal-invalid") throw error;
    if (error instanceof TypeError || error instanceof RangeError) bad("input or retained record");
    throw error;
  }
}

function snapshot(value, field) {
  try {
    return canonicalizeJson(value, JSON_RESOURCE_ENVELOPE).value;
  } catch {
    bad(field);
  }
}

function sameKeys(value, keys, field) {
  if (value === null || Array.isArray(value) || typeof value !== "object") bad(field);
  const actual = Object.keys(value).sort();
  const expected = [...keys].sort();
  if (actual.length !== expected.length || actual.some((key, index) => key !== expected[index])) bad(field);
}

function scalarString(value, field) {
  if (typeof value !== "string" || value.length === 0 || [...value].length > 512) bad(field);
  for (let i = 0; i < value.length; i++) {
    const code = value.charCodeAt(i);
    if (code >= 0xd800 && code <= 0xdbff) {
      const next = value.charCodeAt(i + 1);
      if (!(next >= 0xdc00 && next <= 0xdfff)) bad(field);
      i++;
    } else if (code >= 0xdc00 && code <= 0xdfff) bad(field);
  }
  return value;
}

function ordinal(left, right) {
  return left < right ? -1 : left > right ? 1 : 0;
}

function sortedReferences(value, field) {
  if (!Array.isArray(value)) bad(field);
  let previous;
  for (const ref of value) {
    if (!isArtifactRef(ref)) bad(field);
    if (previous !== undefined && ordinal(previous, ref) >= 0) bad(field);
    previous = ref;
  }
  return value;
}

function checkEnvelope() {
  const keys = Object.keys(ENVELOPE).sort();
  const actual = Object.keys(JSON_RESOURCE_ENVELOPE ?? {}).sort();
  if (actual.length !== keys.length || actual.some((key, index) => key !== keys[index])) bad("JSON resource envelope");
  for (const [key, value] of Object.entries(ENVELOPE)) {
    if (JSON_RESOURCE_ENVELOPE[key] !== value) bad("JSON resource envelope");
  }
}

function slotDigest(journal, command) {
  const tuple = ["metroplat.journal.unique-slot", 1, journal, command.domain, command.key];
  const bytes = Buffer.from(canonicalJson(tuple), "utf8");
  return createHash("sha256").update(bytes).digest("hex");
}

function addressCommand(value, journalIdentity) {
  checkEnvelope();
  scalarString(journalIdentity, "journal identity");
  const command = snapshot(value, "command");
  sameKeys(command, ["kind", "version", "domain", "key", "subject", "value", "causes", "artifactRefs"], "command fields");
  if (command.kind !== UNIQUE_COMMAND || command.version !== 1) bad("command kind or version");
  if (command.domain !== "interaction" && command.domain !== "effect-successor") bad("command domain");
  scalarString(command.subject, "command subject");
  if (command.domain === "interaction") {
    sameKeys(command.key, ["context", "principal", "requestId"], "interaction key");
    scalarString(command.key.context, "interaction context");
    scalarString(command.key.principal, "interaction principal");
    scalarString(command.key.requestId, "interaction requestId");
  } else {
    sameKeys(command.key, ["journal", "effectId", "predecessor"], "effect key");
    scalarString(command.key.journal, "effect journal");
    scalarString(command.key.effectId, "effectId");
    if (command.key.journal !== journalIdentity) bad("effect journal correspondence");
    if (command.key.predecessor !== null && !isArtifactRef(command.key.predecessor)) bad("effect predecessor");
  }
  sortedReferences(command.causes, "causes");
  sortedReferences(command.artifactRefs, "artifactRefs");
  if (command.domain === "effect-successor" && command.key.predecessor !== null
    && !command.causes.includes(command.key.predecessor)) bad("predecessor in causes");
  const commandRef = addressArtifact(command).ref;
  return Object.freeze({ command, commandRef, slotDigest: slotDigest(journalIdentity, command) });
}

function source(ref, canonicalText) {
  return Object.freeze({ ref, canonicalText });
}

function sortedUnique(values) {
  return Object.freeze([...new Set(values)].sort(ordinal));
}

export function journalWitness(observation) {
  if (observation.kind !== "metroplat.journal.observation") {
    throw new TypeError("journal observation has an unsupported kind");
  }
  if (observation.time.length === 0) throw new TypeError("journal observation time must be nonempty");
  if (!check(observation.claim)) throw new TypeError("journal observation claim is not a closed typed term");
  if (!check(observation.address)) throw new TypeError("journal observation address is not a closed typed term");

  const site = addressSiteConstitution();
  const token = addressArtifact(Object.freeze({
    kind: "metroplat.journal.address-mark",
    version: 1,
    address: observation.address,
  }));
  const claim = addressArtifact(Object.freeze({
    kind: "metroplat.journal.claim-mark",
    version: 1,
    claim: observation.claim,
    ...(observation.payload === undefined ? {} : { payload: observation.payload }),
  }));
  const boundary = addressArtifact(Object.freeze({
    kind: "metroplat.journal.boundary-observation",
    version: 1,
    seat: observation.seat,
    observedAt: observation.time,
  }));
  const articulation = addressPrimitiveArticulation(Object.freeze({
    kind: "metroplat.primitive-articulation",
    version: 1,
    token: token.ref,
    claim: claim.ref,
  }));
  const artifactRefs = new Set(observation.referencedArtifacts ?? []);
  if (artifactRefs.size !== (observation.referencedArtifacts?.length ?? 0)) {
    throw new TypeError("journal observation repeats a referenced artifact");
  }
  const witnessResult = addressWitnessCore(Object.freeze({
    kind: "metroplat.witness-core",
    version: 1,
    site: site.ref,
    articulation: articulation.ref,
    causes: sortedUnique(observation.causes),
    referencedArtifacts: sortedUnique([boundary.ref, ...artifactRefs]),
    attestationRefs: Object.freeze([]),
    boundaryObservationRefs: Object.freeze([]),
  }));
  if (!isCausalWitness(witnessResult)) throw new TypeError(witnessResult.message);
  const witness = witnessResult.value;
  const sources = Object.freeze([
    source(site.ref, site.canonical.text),
    source(token.ref, token.canonical.text),
    source(claim.ref, claim.canonical.text),
    source(boundary.ref, boundary.canonical.text),
    source(articulation.ref, articulation.canonical.text),
    source(witness.ref, witness.canonical.text),
  ].sort((left, right) => ordinal(left.ref, right.ref)));
  return Object.freeze({
    kind: "metroplat.journal.witness",
    id: witness.ref,
    bytes: witness.canonical.text,
    core: witness.core,
    observation: Object.freeze({
      ...observation,
      causes: sortedUnique(observation.causes),
      ...(artifactRefs.size === 0 ? {} : { referencedArtifacts: sortedUnique([...artifactRefs]) }),
    }),
    sources,
  });
}

export function parseJournalWitness(value) {
  const record = requireJsonValue(value, "journal witness");
  if (record === null || Array.isArray(record) || typeof record !== "object") {
    throw new TypeError("journal witness must be an object");
  }
  const candidate = record;
  if (candidate.kind !== "metroplat.journal.witness") throw new TypeError("unsupported journal witness kind");
  const expected = journalWitness(candidate.observation);
  if (
    candidate.id !== expected.id
    || candidate.bytes !== expected.bytes
    || canonicalJson(candidate.core) !== canonicalJson(expected.core)
  ) {
    throw new TypeError("journal witness does not match its exact observation and causal source material");
  }
  if (!Array.isArray(candidate.sources) || candidate.sources.length !== expected.sources.length) {
    throw new TypeError("journal witness sources do not match the reconstructed source set");
  }
  const expectedByRef = new Map(expected.sources.map((entry) => [entry.ref, entry.canonicalText]));
  const seen = new Set();
  for (const entry of candidate.sources) {
    if (entry === null || Array.isArray(entry) || typeof entry !== "object") {
      throw new TypeError("journal witness source entry must be an object");
    }
    const keys = Object.keys(entry).sort();
    if (keys.length !== 2 || keys[0] !== "canonicalText" || keys[1] !== "ref") {
      throw new TypeError("journal witness source entry has unexpected fields");
    }
    if (typeof entry.ref !== "string" || typeof entry.canonicalText !== "string"
