/** A tuple or object row as the `[e, a, v, t]` tuple. */
export function toEavt(value) {
  const r = eavtRecord(value);
  return Object.freeze([r.e, r.a, r.v, r.t]);
}

/** A row's content address: the ni URI of its record's canonical CBOR. An
